session_start(); require_once __DIR__ . '/../lead-engine/config.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/?next='.rawurlencode($_SERVER['REQUEST_URI']??'/dashboard/goliath-executive-core.php'));exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sbq($ep){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json'],CURLOPT_TIMEOUT=>25]);$b=curl_exec($ch);curl_close($ch);$d=json_decode($b,true);return is_array($d)?$d:[];}
$key=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'timetomakethedonuts';
$tasks=sbq('goliath_tasks?select=*&order=created_at.desc&limit=20');
$ideas=sbq('goliath_ideas?select=*&order=created_at.desc&limit=20');
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Goliath Executive Core</title><link rel="stylesheet" href="/dashboard/assets/goliath-ui.css?v=36"><style>.coreBox{background:#0f172a;border:1px solid #263753;border-radius:16px;padding:12px}.coreAsk textarea{width:100%;min-height:110px;background:#020617;color:#fff;border:1px solid #263753;border-radius:14px;padding:12px;font-weight:800}.coreGrid{display:grid;grid-template-columns:1fr 1fr;gap:14px}@media(max-width:900px){.coreGrid{grid-template-columns:1fr}}</style></head><body><div class="g-shell"><?php require __DIR__.'/includes/goliath-sidebar-v34.php'; ?><main class="g-main"><section class="g-top"><div><h1>Executive Core</h1><p>The central thinking layer for Ask Goliath, ideas, tasks, delegation, and future voice.</p></div><a class="g-btn g-btn-dark" href="/dashboard/goliath-mission-control.php">Mission Control</a></section><section class="g-panel coreAsk"><h2>Talk to Goliath Core <span>text test before voice</span></h2><div class="g-inner"><textarea id="msg" placeholder="Example: Remind me to call Harrison tomorrow. Or: I have a new business idea..."></textarea><br><br><button class="g-btn g-btn-gold" onclick="sendCore()">Ask Goliath Core</button><div id="result" class="coreBox" style="margin-top:12px;color:#cbd5e1">Waiting...</div></div></section><br><div class="coreGrid"><section class="g-panel"><h2>Saved Tasks</h2><div class="g-inner"><?php foreach($tasks as $t):?><div class="coreBox"><strong><?=h($t['title']??'Task')?></strong><p><?=h($t['detail']??'')?></p><small><?=h($t['status']??'open')?> · Priority <?=h($t['priority']??0)?></small></div><br><?php endforeach;?></div></section><section class="g-panel"><h2>Ideas</h2><div class="g-inner"><?php foreach($ideas as $i):?><div class="coreBox"><strong><?=h($i['title']??'Idea')?></strong><p><?=h($i['recommendation']??'')?></p><small>Score <?=h($i['score']??0)?></small></div><br><?php endforeach;?></div></section></div></main></div><script>const KEY=<?=json_encode($key)?>;async function sendCore(){const msg=document.getElementById('msg').value;const r=await fetch('/lead-engine/goliath-executive-core.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:KEY,message:msg})});const j=await r.json();document.getElementById('result').innerHTML='<strong>'+j.intent+' → '+j.department+'</strong><p>'+j.response+'</p><pre style="white-space:pre-wrap">'+JSON.stringify(j.created,null,2)+'</pre>';}</script></body></html>